import{m as e}from"./merge-BmcoofH2.js";const t={"grundlagen-des-wirtschaftens":[{de:{term:"Maslowsche Bedürfnispyramide",erklaerung:"Ordnet Bedürfnisse nach Dringlichkeit, von unten nach oben: Grundbedürfnisse → Sicherheit → soziale Bedürfnisse → Anerkennung → Selbstverwirklichung.",beispiel:"Erst wenn Essen und Wohnung gesichert sind, denkt man an Karriere."},en:{term:"Maslow's hierarchy of needs",erklaerung:"Ranks needs by urgency, from bottom to top: basic needs → safety → social needs → esteem → self-actualisation.",beispiel:"Only once food and housing are secured do people think about a career."},hu:{term:"Maslow-féle szükségleti piramis",erklaerung:"A szükségleteket sürgősségük szerint rendezi alulról felfelé: alapvető szükségletek → biztonság → társas szükségletek → elismerés → önmegvalósítás.",beispiel:"Csak ha az étel és a lakás biztosított, gondol az ember a karrierre."}},{de:{term:"Minimalprinzip vs. Maximalprinzip",erklaerung:"Minimalprinzip: Ziel fix → möglichst geringer Einsatz. Maximalprinzip: Einsatz fix → möglichst großes Ergebnis. Trick: Was ist fix?",beispiel:"Genau 500 Schachteln am günstigsten (Minimal) – mit 200 € möglichst viele Schachteln (Maximal)."},en:{term:"Minimum vs. maximum principle",erklaerung:"Minimum principle: goal fixed → as little input as possible. Maximum principle: input fixed → as large a result as possible. Trick: what is fixed?",beispiel:"Exactly 500 boxes as cheaply as possible (minimum) – as many boxes as possible for €200 (maximum)."},hu:{term:"Minimumelv és maximumelv",erklaerung:"Minimumelv: a cél rögzített → a lehető legkisebb ráfordítás. Maximumelv: a ráfordítás rögzített → a lehető legnagyobb eredmény. Trükk: mi a rögzített?",beispiel:"Pontosan 500 doboz a legolcsóbban (minimum) – 200 €-ból a lehető legtöbb doboz (maximum)."}},{de:{term:"Freie Güter vs. Wirtschaftsgüter",erklaerung:"Freie Güter gibt es unbegrenzt in der Natur, sie sind meist gratis. Wirtschaftsgüter sind knapp und kosten Geld – je knapper, desto teurer.",beispiel:"Sonnenlicht (frei) – Kakao, Erdöl (Wirtschaftsgut)"},en:{term:"Free goods vs. economic goods",erklaerung:"Free goods exist in unlimited quantities in nature and are usually free of charge. Economic goods are scarce and cost money – the scarcer, the more expensive.",beispiel:"Sunlight (free) – cocoa, crude oil (economic good)"},hu:{term:"Szabad javak és gazdasági javak",erklaerung:"A szabad javak korlátlanul állnak rendelkezésre a természetben, és többnyire ingyenesek. A gazdasági javak szűkösek, és pénzbe kerülnek – minél szűkösebbek, annál drágábbak.",beispiel:"Napfény (szabad) – kakaó, kőolaj (gazdasági jószág)"}},{de:{term:"Konsumgut vs. Investitionsgut",erklaerung:"Konsumgüter werden selbst verbraucht oder benutzt, mit Investitionsgütern stellt ein Unternehmen andere Güter her. Entscheidend ist, WER es WOFÜR verwendet.",beispiel:"Auto für Familienausflüge (Konsumgut) – dasselbe Auto als Taxi (Investitionsgut)"},en:{term:"Consumer good vs. capital good",erklaerung:"Consumer goods are used up or used privately; with capital goods a business produces other goods. What matters is WHO uses it FOR WHAT.",beispiel:"Car for family trips (consumer good) – the same car as a taxi (capital good)"},hu:{term:"Fogyasztási jószág és beruházási jószág",erklaerung:"A fogyasztási javakat magunk használjuk el vagy használjuk, a beruházási javakkal a vállalkozás más javakat állít elő. Az a döntő, KI és MIRE használja.",beispiel:"Autó családi kirándulásra (fogyasztási) – ugyanaz az autó taxiként (beruházási)"}},{de:{term:"Sekundärbedürfnisse",erklaerung:"Sammelbegriff für Kultur- und Luxusbedürfnisse – sie sind nicht lebensnotwendig. Gegenteil: Primärbedürfnisse (= Grundbedürfnisse).",beispiel:"Kinobesuch (Kultur), Sportwagen (Luxus)"},en:{term:"Secondary needs",erklaerung:"Umbrella term for cultural and luxury needs – they are not essential for survival. Opposite: primary needs (= basic needs).",beispiel:"Going to the cinema (cultural), sports car (luxury)"},hu:{term:"Másodlagos szükségletek",erklaerung:"A kulturális és a luxusszükségletek gyűjtőneve – nem létfontosságúak. Ellentétük: elsődleges szükségletek (= alapvető szükségletek).",beispiel:"Mozilátogatás (kulturális), sportautó (luxus)"}}],"der-markt":[{de:{term:"Polypol – Oligopol – Monopol",erklaerung:"Marktformen nach Zahl der Teilnehmer: viele (Polypol), wenige (Oligopol), einer (Monopol). Je weniger Teilnehmer, desto mehr Marktmacht.",beispiel:"Kleidung (Polypol), Mobilfunk (Oligopol), Glücksspiel (Monopol)"},en:{term:"Polypoly – oligopoly – monopoly",erklaerung:"Market forms by number of participants: many (polypoly), few (oligopoly), one (monopoly). The fewer participants, the more market power.",beispiel:"Clothing (polypoly), mobile phone networks (oligopoly), gambling (monopoly)"},hu:{term:"Polipólium – oligopólium – monopólium",erklaerung:"Piaci formák a szereplők száma szerint: sok (polipólium), kevés (oligopólium), egy (monopólium). Minél kevesebb a szereplő, annál nagyobb a piaci erő.",beispiel:"Ruházat (polipólium), mobilszolgáltatók (oligopólium), szerencsejáték (monopólium)"}},{de:{term:"Angebots- vs. Nachfrageüberschuss",erklaerung:"Preis über dem Gleichgewichtspreis → angebotene Menge > nachgefragte Menge (Angebotsüberschuss). Preis darunter → Nachfrageüberschuss.",beispiel:"Zu teure Adventskalender bleiben im Regal liegen (Angebotsüberschuss)."},en:{term:"Excess supply vs. excess demand",erklaerung:"Price above the equilibrium price → quantity supplied > quantity demanded (excess supply). Price below it → excess demand.",beispiel:"Overpriced Advent calendars stay on the shelf (excess supply)."},hu:{term:"Kínálati többlet és keresleti többlet",erklaerung:"Ha az ár az egyensúlyi ár felett van → kínált mennyiség > keresett mennyiség (kínálati többlet). Ha alatta → keresleti többlet.",beispiel:"A túl drága adventi naptárak a polcon maradnak (kínálati többlet)."}},{de:{term:"Wirtschaftssektoren",erklaerung:"Primär = Urproduktion (Rohstoffe gewinnen), sekundär = Produktion (Rohstoffe verarbeiten), tertiär = Dienstleistung (Handel, Bank, Friseur).",beispiel:"Forst (primär) → Sägewerk (sekundär) → Möbelhaus (tertiär)"},en:{term:"Economic sectors",erklaerung:"Primary = extraction of raw materials, secondary = production (processing raw materials), tertiary = services (retail, banks, hairdressers).",beispiel:"Forestry (primary) → sawmill (secondary) → furniture store (tertiary)"},hu:{term:"Gazdasági szektorok",erklaerung:"Primer = őstermelés (nyersanyag-kitermelés), szekunder = termelés (nyersanyagok feldolgozása), tercier = szolgáltatás (kereskedelem, bank, fodrász).",beispiel:"Erdőgazdaság (primer) → fűrészüzem (szekunder) → bútoráruház (tercier)"}},{de:{term:"Planwirtschaft",erklaerung:"Der Staat plant die ganze Wirtschaft zentral in einem Gesamtplan und bestimmt die Preise. Es gibt keinen Wettbewerb; oft entstehen zu viele oder zu wenige Güter.",beispiel:"Nordkorea, teilweise Kuba"},en:{term:"Planned economy",erklaerung:"The state plans the entire economy centrally in an overall plan and sets prices. There is no competition; often too many or too few goods are produced.",beispiel:"North Korea, partly Cuba"},hu:{term:"Tervgazdaság",erklaerung:"Az állam központilag, egy átfogó tervben tervezi az egész gazdaságot, és meghatározza az árakat. Nincs verseny; gyakran túl sok vagy túl kevés jószág készül.",beispiel:"Észak-Korea, részben Kuba"}},{de:{term:"Innerbetriebliche, nationale und internationale Arbeitsteilung",erklaerung:"Innerbetrieblich: Abteilungen in EINER Firma. National: verschiedene Firmen in einem Land. International: verschiedene Länder.",beispiel:"Einkauf/Verkauf bei Loopy – Bauer & Molkerei – Kakao aus Ecuador"},en:{term:"In-company, national and international division of labour",erklaerung:"In-company: departments within ONE firm. National: different firms in one country. International: different countries.",beispiel:"Purchasing/sales at Loopy's – farmer & dairy – cocoa from Ecuador"},hu:{term:"Üzemen belüli, nemzeti és nemzetközi munkamegosztás",erklaerung:"Üzemen belüli: osztályok EGY cégen belül. Nemzeti: különböző cégek egy országon belül. Nemzetközi: különböző országok között.",beispiel:"Beszerzés/értékesítés Loopynál – gazda és tejüzem – kakaó Ecuadorból"}}],"unternehmen-und-umfeld":[{de:{term:"Unternehmen – Betrieb – Firma",erklaerung:"Unternehmen = rechtlicher Rahmen (schließt Geschäfte ab). Betrieb = Ort der Leistungserstellung (es kann mehrere geben). Firma = Name im Firmenbuch.",beispiel:"Eine Bäckerei-GmbH mit Backstube und 3 Filialen: 1 Unternehmen, 4 Betriebe, 1 Firma"},en:{term:"Business – operating site – company name",erklaerung:"Unternehmen = legal framework (concludes deals). Betrieb = place where output is produced (there can be several). Firma = name in the commercial register.",beispiel:"A bakery GmbH with a bakehouse and 3 branches: 1 business, 4 sites, 1 company name"},hu:{term:"Vállalkozás – üzem – cégnév",erklaerung:"Vállalkozás = jogi keret (ügyleteket köt). Üzem = a teljesítmény-előállítás helye (több is lehet). Cégnév = a cégjegyzékbe bejegyzett név.",beispiel:"Egy pékség-GmbH sütödével és 3 fiókkal: 1 vállalkozás, 4 üzem, 1 cégnév"}},{de:{term:"Sachziel vs. Formalziel",erklaerung:"Sachziel: WAS konkret geleistet wird (Menge, Zeit, Qualität). Formalziel: allgemeines wirtschaftliches Ziel, unabhängig von der Branche – monetär oder nicht monetär.",beispiel:"Morgen 25 Linzer Torten (Sachziel) – Umsatz +10 % (Formalziel)"},en:{term:"Operational goal vs. formal goal",erklaerung:"Operational (material) goal: WHAT exactly is produced (quantity, time, quality). Formal goal: general economic goal independent of the industry – monetary or non-monetary.",beispiel:"25 Linzer tortes tomorrow (operational) – revenue +10% (formal)"},hu:{term:"Tárgyi cél és formális cél",erklaerung:"Tárgyi cél: MIT állítanak elő konkrétan (mennyiség, idő, minőség). Formális cél: ágazattól független, általános gazdasági cél – pénzben mérhető vagy nem pénzben mérhető.",beispiel:"Holnap 25 linzi torta (tárgyi cél) – árbevétel +10% (formális cél)"}},{de:{term:"SMART-Ziele",erklaerung:"Gute Ziele sind spezifisch (präzise), messbar (überprüfbar), attraktiv (motivierend), realistisch (erreichbar) und terminiert (mit Frist).",beispiel:"„Bis 31. Dezember steigern wir den Online-Umsatz um 8 %.“"},en:{term:"SMART goals",erklaerung:"Good goals are specific (precise), measurable (verifiable), attractive (motivating), realistic (achievable) and time-bound (with a deadline).",beispiel:"“By 31 December we will increase online sales by 8%.”"},hu:{term:"SMART-célok",erklaerung:"A jó cél specifikus (pontos), mérhető (ellenőrizhető), vonzó (motiváló), reális (elérhető) és határidőhöz kötött.",beispiel:"„December 31-ig 8%-kal növeljük az online árbevételt.”"}},{de:{term:"Profit- vs. Non-Profit-Organisation",erklaerung:"Profit: private Unternehmen, erfolgreich bei Erträgen > Aufwänden. Non-Profit: arbeitet für die Allgemeinheit, Kostendeckung reicht; Verluste trägt z. B. der Staat.",beispiel:"Konditorei (Profit) – öffentliches Krankenhaus, Verein (Non-Profit)"},en:{term:"Profit vs. non-profit organisation",erklaerung:"Profit: private businesses, successful when income > expenses. Non-profit: works for the public good, covering costs is enough; losses are borne e.g. by the state.",beispiel:"Patisserie (profit) – public hospital, association (non-profit)"},hu:{term:"Profitorientált és nonprofit szervezet",erklaerung:"Profitorientált: magánvállalkozás, sikeres, ha bevétel > ráfordítás. Nonprofit: a közösségért dolgozik, elég a költségfedezet; a veszteséget pl. az állam állja.",beispiel:"Cukrászda (profitorientált) – közkórház, egyesület (nonprofit)"}},{de:{term:"Betriebsgrößen",erklaerung:"Nach Mitarbeiter:innen: Kleinstbetrieb bis 9, Kleinbetrieb 10–49, Mittelbetrieb 50–249, Großbetrieb ab 250. Auch Umsatz und Bilanzsumme spielen eine Rolle.",beispiel:"Loopys Candy Store mit 4 Mitarbeiter:innen = Kleinstbetrieb"},en:{term:"Business sizes",erklaerung:"By employees: micro up to 9, small 10–49, medium-sized 50–249, large 250 or more. Revenue and balance sheet total also play a role.",beispiel:"Loopy's Candy Store with 4 employees = micro business"},hu:{term:"Vállalkozási méretek",erklaerung:"A munkavállalók száma szerint: mikro legfeljebb 9, kis 10–49, közép 50–249, nagy legalább 250 fő. Az árbevétel és a mérlegfőösszeg is számít.",beispiel:"Loopy édességboltja 4 munkavállalóval = mikrovállalkozás"}}],"leistungserstellung-1jg":[{de:{term:"Roh-, Hilfs- und Betriebsstoffe (Werkstoffe)",erklaerung:"Rohstoff = Hauptbestandteil des Produkts, Hilfsstoff = Nebenbestandteil, Betriebsstoff = wird verbraucht, ist aber nicht im Produkt.",beispiel:"Jeans: Jeansstoff (Roh), Zwirn (Hilfs), Öl für die Nähmaschine (Betrieb)"},en:{term:"Raw, auxiliary and operating materials",erklaerung:"Raw material = main component of the product, auxiliary material = minor component, operating supply = used up but not part of the product.",beispiel:"Jeans: denim (raw), thread (auxiliary), oil for the sewing machine (operating)"},hu:{term:"Nyers-, segéd- és üzemanyagok (anyagok)",erklaerung:"Nyersanyag = a termék fő alkotórésze, segédanyag = mellékes alkotórész, üzemanyag = elhasználódik, de nincs benne a termékben.",beispiel:"Farmer: farmeranyag (nyers), cérna (segéd), olaj a varrógéphez (üzem)"}},{de:{term:"Handelswaren",erklaerung:"Fertig gekaufte Güter, die unverändert weiterverkauft werden. Sie gehören zum Umlaufvermögen – im Gegensatz zu selbst hergestellten Erzeugnissen.",beispiel:"Loopy verkauft zugekaufte Geschenkkarten neben ihren eigenen Pralinen."},en:{term:"Merchandise",erklaerung:"Goods bought ready-made and resold unchanged. They belong to current assets – unlike self-made products.",beispiel:"Loopy sells bought-in gift cards alongside her own chocolates."},hu:{term:"Kereskedelmi áruk",erklaerung:"Készen vásárolt javak, amelyeket változatlanul adnak tovább. A forgóeszközök közé tartoznak – szemben a saját gyártású termékekkel.",beispiel:"Loopy saját bonbonjai mellett vásárolt ajándékkártyákat is árul."}},{de:{term:"Grundfunktionen des Unternehmens",erklaerung:"Beschaffung → Produktion → Absatz hängen direkt am Produkt. Unterstützt von Lager, Personalwesen und Rechnungswesen; darüber steht die Unternehmensführung.",beispiel:"Kakao einkaufen → Pralinen herstellen → im Laden verkaufen"},en:{term:"Core functions of a business",erklaerung:"Procurement → production → sales are directly linked to the product. They are supported by storage, HR and accounting, with management on top.",beispiel:"Buy cocoa → make chocolates → sell them in the shop"},hu:{term:"A vállalkozás alapfunkciói",erklaerung:"Beszerzés → termelés → értékesítés közvetlenül a termékhez kötődik. Támogatja őket a raktár, a HR és a számvitel; felettük áll a vállalatvezetés.",beispiel:"Kakaó beszerzése → bonbon gyártása → eladás a boltban"}},{de:{term:"Lagerarten",erklaerung:"Beschaffungslager (gekaufte Materialien vor der Produktion) → Zwischenlager (unfertige Güter zwischen Produktionsschritten) → Verkaufs- und Versandlager (fertige Produkte).",beispiel:"Kakaobohnen – halbfertige Pralinenmasse – verpackte Schachteln"},en:{term:"Types of storage",erklaerung:"Procurement storage (purchased materials before production) → intermediate storage (unfinished goods between steps) → sales and dispatch storage (finished products).",beispiel:"Cocoa beans – semi-finished praline mass – packed boxes"},hu:{term:"Raktártípusok",erklaerung:"Beszerzési raktár (vásárolt anyagok gyártás előtt) → közbenső raktár (félkész termékek a gyártási lépések között) → értékesítési és szállítási raktár (késztermékek).",beispiel:"Kakaóbab – félkész bonbonmassza – becsomagolt dobozok"}},{de:{term:"Leistungsfähigkeit vs. Leistungsbereitschaft",erklaerung:"Leistungsfähigkeit = Können (Begabung, Ausbildung, Erfahrung, Alter). Leistungsbereitschaft = Wollen, also Motivation (Lohn, Betriebsklima, Arbeitszeiten, Lob).",beispiel:"Eine top ausgebildete Konditorin arbeitet bei schlechtem Klima trotzdem lustlos."},en:{term:"Ability vs. willingness to perform",erklaerung:"Ability = being able to (talent, training, experience, age). Willingness = wanting to, i.e. motivation (pay, working atmosphere, working hours, praise).",beispiel:"A highly trained confectioner still works half-heartedly in a bad atmosphere."},hu:{term:"Teljesítőképesség és teljesítményhajlandóság",erklaerung:"Teljesítőképesség = tudás (tehetség, képzettség, tapasztalat, életkor). Teljesítményhajlandóság = akarás, vagyis motiváció (bér, légkör, munkaidő, dicséret).",beispiel:"Egy kiválóan képzett cukrász rossz légkörben mégis kedvetlenül dolgozik."}}],"phasen-kaufen-verkaufen":[{de:{term:"Bindungsdauer eines Angebots",erklaerung:"Mit Frist: so lange wie angegeben. Ohne Frist: mündlich nur während des Gesprächs, Brief = Überlegungsfrist + doppelter Postweg, E-Mail = angemessene Überlegungsfrist.",beispiel:"Brief ohne Frist: gebunden ca. 4–6 Tage"},en:{term:"Binding period of an offer",erklaerung:"With a deadline: as long as stated. Without: oral only during the conversation, letter = time to consider + double postal route, e-mail = reasonable time to consider.",beispiel:"Letter without a deadline: bound for about 4–6 days"},hu:{term:"Az ajánlati kötöttség időtartama",erklaerung:"Határidővel: a megadott ideig. Anélkül: szóban csak a beszélgetés alatt, levélnél gondolkodási idő + kétszeres postai út, e-mailnél megfelelő gondolkodási idő.",beispiel:"Határidő nélküli levél: kb. 4–6 napig köt"}},{de:{term:"Schwebend unwirksam",erklaerung:"Ein Vertrag, den ein Minderjähriger über seine Geschäftsfähigkeit hinaus abschließt, ist zunächst in der Schwebe: gültig erst mit Zustimmung der Eltern, sonst ungültig.",beispiel:"Ein 13-Jähriger kauft ohne Erlaubnis ein Handy um 400 €."},en:{term:"Provisionally ineffective (pending)",erklaerung:"A contract a minor concludes beyond their legal capacity is initially pending: it only becomes valid with the parents' consent, otherwise it is invalid.",beispiel:"A 13-year-old buys a €400 phone without permission."},hu:{term:"Függő hatályú szerződés",erklaerung:"Az a szerződés, amelyet egy kiskorú az ügyleti képességén túl köt, kezdetben függőben van: csak a szülők jóváhagyásával válik érvényessé, különben érvénytelen.",beispiel:"Egy 13 éves engedély nélkül vesz egy 400 €-s mobilt."}},{de:{term:"Schlüssiges Handeln",erklaerung:"Ein Vertrag kommt ohne Worte zustande, weil das Verhalten eindeutig zeigt, was man will. Möglich, weil grundsätzlich Formfreiheit gilt.",beispiel:"Geld in den Getränkeautomaten werfen"},en:{term:"Implied conduct",erklaerung:"A contract is formed without words because the behaviour clearly shows what someone wants. Possible because freedom of form applies in principle.",beispiel:"Putting money into a drinks vending machine"},hu:{term:"Ráutaló magatartás",erklaerung:"A szerződés szavak nélkül jön létre, mert a viselkedés egyértelműen mutatja, mit akar valaki. Azért lehetséges, mert alapvetően formaszabadság van.",beispiel:"Pénz bedobása egy italautomatába"}},{de:{term:"Unbestellte Ware",erklaerung:"Schweigen einer Privatperson gilt als Ablehnung. Wer unbestellte Ware bekommt, muss sie weder bezahlen noch zurückschicken.",beispiel:"Ein Versandhaus schickt ungefragt ein Buch samt Zahlschein – du musst nichts tun."},en:{term:"Unsolicited goods",erklaerung:"Silence from a private person counts as rejection. Anyone who receives goods they did not order need neither pay for them nor send them back.",beispiel:"A mail-order company sends you a book with a payment slip unasked – you don't have to do anything."},hu:{term:"Meg nem rendelt áru",erklaerung:"Egy magánszemély hallgatása elutasításnak számít. Aki meg nem rendelt árut kap, annak sem kifizetnie, sem visszaküldenie nem kell.",beispiel:"Egy csomagküldő kéretlenül küld egy könyvet befizetési lappal – semmit sem kell tenned."}},{de:{term:"Voraussetzungen für einen gültigen Vertrag",erklaerung:"Zweiseitigkeit, übereinstimmende Willenserklärung, Freiwilligkeit, Erlaubtheit, Möglichkeit und Geschäftsfähigkeit. Fehlt eine, ist der Vertrag nicht gültig.",beispiel:"Ein Grundstück am Jupiter zu verkaufen scheitert an der Möglichkeit."},en:{term:"Requirements for a valid contract",erklaerung:"Two parties, matching declarations of intent, voluntariness, legality, possibility and legal capacity. If one is missing, the contract is not valid.",beispiel:"Selling a plot of land on Jupiter fails for lack of possibility."},hu:{term:"Az érvényes szerződés feltételei",erklaerung:"Kétoldalúság, egybehangzó akaratnyilatkozat, önkéntesség, jogszerűség, lehetőség és ügyleti képesség. Ha egy hiányzik, a szerződés nem érvényes.",beispiel:"Egy telek eladása a Jupiteren a lehetőség hiánya miatt bukik el."}}],"gesetzliche-grundlagen-kauf":[{de:{term:"C2C – B2C – B2B",erklaerung:"Geschäftsarten nach den Vertragspartnern: privat → privat (C2C), Unternehmen → privat (B2C), Unternehmen → Unternehmen (B2B).",beispiel:"Handy auf eBay (C2C) – Torte in der Konditorei (B2C) – Billa kauft Milch bei Schärdinger (B2B)"},en:{term:"C2C – B2C – B2B",erklaerung:"Types of transactions by contracting parties: private → private (C2C), business → private (B2C), business → business (B2B).",beispiel:"Phone on eBay (C2C) – cake at a patisserie (B2C) – Billa buys milk from Schärdinger (B2B)"},hu:{term:"C2C – B2C – B2B",erklaerung:"Ügylettípusok a szerződő felek szerint: magán → magán (C2C), vállalkozás → magán (B2C), vállalkozás → vállalkozás (B2B).",beispiel:"Mobil az eBay-en (C2C) – torta a cukrászdában (B2C) – a Billa tejet vesz a Schärdingertől (B2B)"}},{de:{term:"ABGB",erklaerung:"Allgemeines bürgerliches Gesetzbuch: gilt für ALLE Verträge, egal wer sie abschließt – z. B. Regeln zur Geschäftsfähigkeit.",beispiel:"Gilt beim Fahrradverkauf unter Nachbarn genauso wie beim Einkauf eines Konzerns."},en:{term:"ABGB (Austrian Civil Code)",erklaerung:"General Civil Code: applies to ALL contracts, no matter who concludes them – e.g. rules on legal capacity.",beispiel:"Applies to a bike sale between neighbours just as to a corporation's purchasing."},hu:{term:"ABGB (osztrák polgári törvénykönyv)",erklaerung:"Általános polgári törvénykönyv: MINDEN szerződésre vonatkozik, bárki köti is – pl. az ügyleti képesség szabályai.",beispiel:"Ugyanúgy érvényes két szomszéd kerékpáreladására, mint egy konszern beszerzésére."}},{de:{term:"KSchG",erklaerung:"Konsumentenschutzgesetz: schützt Privatpersonen vor unfairen Methoden von Unternehmen. Gilt nur bei B2C und kann nicht vertraglich ausgeschlossen werden.",beispiel:"Eine Klausel „KSchG gilt nicht“ auf dem Bestellschein ist wirkungslos."},en:{term:"KSchG (Consumer Protection Act)",erklaerung:"Protects private persons from unfair practices by businesses. Applies only to B2C and cannot be excluded by contract.",beispiel:"A clause “KSchG does not apply” on an order form has no effect."},hu:{term:"KSchG (fogyasztóvédelmi törvény)",erklaerung:"Védi a magánszemélyeket a vállalkozások tisztességtelen módszereivel szemben. Csak B2C esetén érvényes, és szerződéssel nem zárható ki.",beispiel:"A megrendelőlapon szereplő „a KSchG nem érvényes” kikötés hatástalan."}},{de:{term:"UGB",erklaerung:"Unternehmensgesetzbuch: regelt Verträge zwischen Unternehmen (B2B) – zusätzlich zum ABGB.",beispiel:"Loopy kauft 50 kg Kakao beim Großhändler."},en:{term:"UGB (Austrian Commercial Code)",erklaerung:"Business Code: governs contracts between businesses (B2B) – in addition to the ABGB.",beispiel:"Loopy buys 50 kg of cocoa from a wholesaler."},hu:{term:"UGB (osztrák vállalati törvénykönyv)",erklaerung:"Vállalati törvénykönyv: a vállalkozások közötti (B2B) szerződéseket szabályozza – az ABGB mellett.",beispiel:"Loopy 50 kg kakaót vesz a nagykereskedőtől."}},{de:{term:"FAGG",erklaerung:"Fern- und Auswärtsgeschäfte-Gesetz: gilt für Verträge zwischen Unternehmen und Privatpersonen, die außerhalb des Geschäftslokals geschlossen werden – online, telefonisch, an der Haustür.",beispiel:"Bestellung in Loopys Onlineshop, Staubsaugerverkauf an der Haustür"},en:{term:"FAGG (Distance and Off-Premises Contracts Act)",erklaerung:"Applies to contracts between businesses and private persons concluded outside the business premises – online, by phone, at the door.",beispiel:"Order in Loopy's online shop, vacuum cleaner sold at the door"},hu:{term:"FAGG (távollévők közötti és üzlethelyiségen kívüli szerződésekről szóló törvény)",erklaerung:"A vállalkozás és magánszemély között az üzlethelyiségen kívül kötött szerződésekre vonatkozik – online, telefonon, házaló értékesítésnél.",beispiel:"Rendelés Loopy webáruházában, porszívóeladás az ajtóban"}},{de:{term:"ECG",erklaerung:"E-Commerce-Gesetz: gilt für Verkäufer:innen mit Website oder Onlineauftritt, z. B. mit Informationspflichten auf der Website.",beispiel:"Loopys Onlineshop braucht ein vollständiges Impressum."},en:{term:"ECG (E-Commerce Act)",erklaerung:"Applies to sellers with a website or online presence, e.g. information obligations on the website.",beispiel:"Loopy's online shop needs a complete legal notice (imprint)."},hu:{term:"ECG (e-kereskedelmi törvény)",erklaerung:"Weboldallal vagy online jelenléttel rendelkező eladókra vonatkozik, pl. a weboldalon kötelező tájékoztatások.",beispiel:"Loopy webáruházának teljes impresszumra van szüksége."}},{de:{term:"Inhaltsfreiheit",erklaerung:"Den Vertragsinhalt dürfen die Partner grundsätzlich frei bestimmen. Grenzen setzen Gesetze wie ABGB, KSchG oder UGB, die trotzdem gelten.",beispiel:"Preis und Liefertermin frei vereinbar – den Konsumentenschutz wegverhandeln nicht."},en:{term:"Freedom of content",erklaerung:"The parties may in principle determine the content of the contract freely. Limits are set by laws such as the ABGB, KSchG or UGB, which still apply.",beispiel:"Price and delivery date can be agreed freely – consumer protection cannot be negotiated away."},hu:{term:"Tartalmi szabadság",erklaerung:"A felek a szerződés tartalmát alapvetően szabadon határozhatják meg. Határt szabnak az olyan törvények, mint az ABGB, a KSchG vagy az UGB, amelyek ettől függetlenül érvényesek.",beispiel:"Az ár és a szállítási határidő szabadon kiköthető – a fogyasztóvédelem nem alkudható el."}},{de:{term:"Kaufvertrag vs. Werkvertrag",erklaerung:"Kaufvertrag: ein fertiges Produkt gegen Kaufpreis. Werkvertrag: ein Werk wird erst hergestellt oder repariert – gegen Werklohn.",beispiel:"Standardkasten aus dem Lager (Kauf) – Kasten nach Maß oder Reparatur (Werk)"},en:{term:"Purchase contract vs. contract for work",erklaerung:"Purchase contract: a finished product for a purchase price. Contract for work: a piece of work is first made or repaired – for a fee.",beispiel:"Standard wardrobe from stock (purchase) – made-to-measure wardrobe or repair (work)"},hu:{term:"Adásvételi szerződés és vállalkozási szerződés",erklaerung:"Adásvételi szerződés: kész termék vételár ellenében. Vállalkozási szerződés: egy művet előbb elkészítenek vagy megjavítanak – vállalkozói díj ellenében.",beispiel:"Szabványos szekrény raktárról (adásvétel) – méretre készült szekrény vagy javítás (vállalkozás)"}}]},r={"fernabsatz-ecommerce":[{de:{term:"FAGG (Fern- und Auswärtsgeschäfte-Gesetz)",erklaerung:"Österreichisches Gesetz für Verträge im Fernabsatz und außerhalb der Geschäftsräume: regelt Informationspflichten, den Bestellbutton und das 14-tägige Rücktrittsrecht von Konsument:innen.",beispiel:"Gilt für Loopys Onlineshop, nicht für Käufe im Laden"},en:{term:"FAGG (Distance and Off-Premises Contracts Act)",erklaerung:"Austrian law for distance contracts and contracts concluded off business premises: regulates duties to inform, the order button and consumers' 14-day right of withdrawal.",beispiel:"Applies to Loopy's online shop, not to purchases in her store"},hu:{term:"FAGG (távollévők között és üzlethelyiségen kívül kötött szerződésekről szóló törvény)",erklaerung:"Osztrák törvény a távértékesítési és az üzlethelyiségen kívül kötött szerződésekről: szabályozza a tájékoztatási kötelezettséget, a megrendelés gombot és a fogyasztók 14 napos elállási jogát.",beispiel:"Loopy webáruházára vonatkozik, a boltban történő vásárlásra nem"}},{de:{term:"ECG (E-Commerce-Gesetz)",erklaerung:"Regelt Pflichten von Anbieter:innen im Internet, z. B. das Impressum mit Name, Anschrift, Kontakt, UID- und Firmenbuchnummer sowie die Bestellbestätigung.",beispiel:"Fehlendes Impressum im Webshop = Verstoß gegen das ECG"},en:{term:"ECG (E-Commerce Act)",erklaerung:"Regulates the duties of online providers, e.g. the legal notice (Impressum) with name, address, contact, VAT ID and company register number, as well as the order confirmation.",beispiel:"No legal notice in the web shop = breach of the ECG"},hu:{term:"ECG (e-kereskedelmi törvény)",erklaerung:"Az internetes szolgáltatók kötelezettségeit szabályozza, pl. az impresszumot (név, cím, elérhetőség, közösségi adószám, cégjegyzékszám) és a megrendelés visszaigazolását.",beispiel:"Hiányzó impresszum a webshopban = az ECG megsértése"}},{de:{term:"Impressum",erklaerung:"Pflichtangaben über den Anbieter auf der Website: Name/Firma, Anschrift, Kontakt, UID-Nummer, Firmenbuchnummer, Aufsichtsbehörde und Kammer. Zeigt, wer hinter dem Shop steht.",beispiel:"Loopys Candy Store, Hauptplatz 1, 8010 Graz, UID ATU…"},en:{term:"Legal notice (Impressum)",erklaerung:"Mandatory information about the provider on the website: name/company, address, contact, VAT ID, company register number, supervisory authority and chamber. Shows who is behind the shop.",beispiel:"Loopys Candy Store, Hauptplatz 1, 8010 Graz, VAT ID ATU…"},hu:{term:"Impresszum",erklaerung:"Kötelező adatok a szolgáltatóról a weboldalon: név/cégnév, cím, elérhetőség, közösségi adószám, cégjegyzékszám, felügyeleti hatóság és kamara. Megmutatja, ki áll a webáruház mögött.",beispiel:"Loopys Candy Store, Hauptplatz 1, 8010 Graz, közösségi adószám: ATU…"}},{de:{term:"Fake Shop",erklaerung:"Betrügerischer Onlineshop, der echt wirkt, nach der (Voraus-)Zahlung aber nie liefert. Warnzeichen: fehlendes Impressum, nur Vorauskasse, unrealistisch billige Preise.",beispiel:"Markensneaker um 70 % billiger, Zahlung nur per Vorauskasse"},en:{term:"Fake shop",erklaerung:"Fraudulent online shop that looks genuine but never delivers after (advance) payment. Warning signs: no legal notice, advance payment only, unrealistically low prices.",beispiel:"Brand sneakers 70% cheaper, payment only in advance"},hu:{term:"Kamu webshop",erklaerung:"Csaló webáruház, amely valódinak tűnik, de az (előre) fizetés után soha nem szállít. Figyelmeztető jelek: nincs impresszum, csak előre fizetés, irreálisan alacsony árak.",beispiel:"Márkás sportcipő 70%-kal olcsóbban, csak előre fizetéssel"}},{de:{term:"E-Commerce-Gütezeichen",erklaerung:"Prüfsiegel für Onlineshops, die geprüfte Standards (Information, Datenschutz, Sicherheit, Rücktritt) einhalten. Hilft Kund:innen, seriöse Shops aus der EU zu erkennen.",beispiel:"Siegel im Footer des Shops, das auf die Prüfstelle verlinkt"},en:{term:"E-commerce trust mark",erklaerung:"Quality seal for online shops that meet audited standards (information, data protection, security, withdrawal). Helps customers recognise reputable EU shops.",beispiel:"Seal in the shop's footer linking to the certifying body"},hu:{term:"E-kereskedelmi minőségi jelzés",erklaerung:"Minőségi pecsét azoknak a webáruházaknak, amelyek ellenőrzött előírásokat (tájékoztatás, adatvédelem, biztonság, elállás) tartanak be. Segít felismerni a megbízható EU-s boltokat.",beispiel:"Pecsét a webáruház láblécében, amely a tanúsító szervezetre mutat"}}],ruecktrittsrechte:[{de:{term:"Umtauschrecht",erklaerung:"Gibt es im Gesetz NICHT. Es besteht nur, wenn es vereinbart ist (z. B. auf der Rechnung). Dann darf der Verkäufer statt Geld auch einen Gutschein geben.",beispiel:"„Umtausch innerhalb von 14 Tagen gegen Vorlage der Rechnung“"},en:{term:"Right of exchange",erklaerung:"Does NOT exist by law. It only exists if agreed (e.g. on the receipt). The seller may then give a voucher instead of money.",beispiel:"“Exchange within 14 days on presentation of the receipt”"},hu:{term:"Cserejog",erklaerung:"A törvény NEM írja elő. Csak akkor létezik, ha megállapodtak róla (pl. a számlán). Ilyenkor az eladó pénz helyett utalványt is adhat.",beispiel:"„Csere 14 napon belül a számla bemutatásával”"}},{de:{term:"Rücktrittsfrist (Fernabsatz/Auswärtsgeschäft)",erklaerung:"14 Kalendertage ab Vertragsabschluss (Ware sofort übergeben) bzw. ab Lieferung. Ohne Belehrung über das Rücktrittsrecht: 1 Jahr + 14 Tage.",beispiel:"Geliefert am 7. August → Rücktritt bis 21. August"},en:{term:"Withdrawal period (distance/off-premises)",erklaerung:"14 calendar days from conclusion of the contract (goods handed over at once) or from delivery. Without information on the right of withdrawal: 1 year + 14 days.",beispiel:"Delivered on 7 August → withdrawal until 21 August"},hu:{term:"Elállási határidő (távértékesítés/üzlethelyiségen kívül)",erklaerung:"14 naptári nap a szerződéskötéstől (ha az árut azonnal átadták), illetve a kiszállítástól. Ha nem tájékoztattak az elállási jogról: 1 év + 14 nap.",beispiel:"Kiszállítás augusztus 7-én → elállás augusztus 21-ig"}},{de:{term:"Auswärtsgeschäft",erklaerung:"Vertrag, der außerhalb der Geschäftsräume des Unternehmens geschlossen wird, z. B. an der Haustür oder auf einer Werbefahrt. Konsument:innen haben 14 Tage Rücktrittsrecht.",beispiel:"Vertreter verkauft an der Wohnungstür einen Staubsauger"},en:{term:"Off-premises contract",erklaerung:"Contract concluded outside the company's business premises, e.g. at the front door or on a promotional trip. Consumers have a 14-day right of withdrawal.",beispiel:"A sales rep sells a vacuum cleaner at the front door"},hu:{term:"Üzlethelyiségen kívül kötött szerződés",erklaerung:"A vállalkozás üzlethelyiségén kívül kötött szerződés, pl. az ajtóban vagy egy reklámúton. A fogyasztóknak 14 napos elállási joguk van.",beispiel:"Egy ügynök a lakásajtóban porszívót ad el"}},{de:{term:"Ausnahmen vom Rücktrittsrecht",erklaerung:"Kein Rücktritt bei Lebensmittel-Hauszustellung, Sonderanfertigungen, entsiegelter Software/CD/DVD, dringenden Reparaturen und Freizeitdienstleistungen mit fixem Termin.",beispiel:"Pizza, Fotobuch, Theaterkarte, gerufener Installateur"},en:{term:"Exceptions to the right of withdrawal",erklaerung:"No withdrawal for home delivery of food, custom-made goods, unsealed software/CDs/DVDs, urgent repairs and leisure services for a fixed date.",beispiel:"Pizza, photo book, theatre ticket, plumber called out"},hu:{term:"Az elállási jog alóli kivételek",erklaerung:"Nincs elállás élelmiszerek házhoz szállításánál, egyedi gyártásnál, felbontott szoftvernél/CD-nél/DVD-nél, sürgős javításnál és időponthoz kötött szabadidős szolgáltatásnál.",beispiel:"Pizza, fotókönyv, színházjegy, kihívott vízszerelő"}},{de:{term:"Kosten nach dem Rücktritt",erklaerung:"Die Käuferin zahlt die Rücksendung, wenn sie darüber informiert wurde. Wurde die Ware benutzt, darf der Verkäufer eine Entschädigung verlangen; den Kaufpreis muss er zurückzahlen.",beispiel:"Kleid getragen → Händler zieht Wertverlust ab"},en:{term:"Costs after withdrawal",erklaerung:"The buyer pays for the return if she was informed about it. If the goods were used, the seller may claim compensation; he must refund the purchase price.",beispiel:"Dress worn → retailer deducts the loss in value"},hu:{term:"Költségek elállás után",erklaerung:"A visszaküldést a vevő fizeti, ha erről tájékoztatták. Ha az árut használták, az eladó kártérítést követelhet; a vételárat vissza kell fizetnie.",beispiel:"Felvett ruha → a kereskedő levonja az értékcsökkenést"}}],"bestandteile-kaufvertrag":[{de:{term:"Gesetzliche Bestandteile des Kaufvertrags",erklaerung:"Müssen immer vereinbart werden: Verkäufer, Käufer, Qualität, Menge und Preis. Liefer- und Zahlungsbedingungen sind zusätzliche kaufmännische Bestandteile.",beispiel:"Loopy kauft beim Großhändler 50 kg Kakao, Qualität „Fairtrade“, zu 8 €/kg"},en:{term:"Statutory elements of the contract of sale",erklaerung:"Must always be agreed: seller, buyer, quality, quantity and price. Terms of delivery and payment are additional commercial elements.",beispiel:"Loopy buys 50 kg of cocoa, “Fairtrade” quality, at €8/kg from the wholesaler"},hu:{term:"Az adásvételi szerződés törvényi elemei",erklaerung:"Mindig meg kell állapodni róluk: eladó, vevő, minőség, mennyiség és ár. A szállítási és fizetési feltételek kiegészítő kereskedelmi elemek.",beispiel:"Loopy 50 kg „Fairtrade” minőségű kakaót vesz a nagykereskedőtől 8 €/kg áron"}},{de:{term:"Kauf nach / auf / zur Probe",erklaerung:"Nach Probe: Ware muss wie die Probe sein. Auf Probe: Rückgabe innerhalb einer Frist möglich. Zur Probe: kleine Menge billig testen, keine Rückgabe.",beispiel:"Fliesenmuster · Matratze · Wandfarbe"},en:{term:"Sale by sample / on approval / trial purchase",erklaerung:"By sample: goods must match the sample. On approval: return possible within a period. Trial purchase: test a small quantity cheaply, no return.",beispiel:"Tile sample · mattress · wall paint"},hu:{term:"Minta szerinti / próbára / kipróbálásra vétel",erklaerung:"Minta szerinti: az árunak olyannak kell lennie, mint a minta. Próbára: határidőn belül visszaadható. Kipróbálásra: kis mennyiség olcsó kipróbálása, nincs visszaadás.",beispiel:"Csempeminta · matrac · falfesték"}},{de:{term:"Draufgabe vs. Dreingabe",erklaerung:"Beides Naturalrabatt. Draufgabe: mehr geliefert als bezahlt. Dreingabe: weniger verrechnet als geliefert.",beispiel:"Draufgabe: 10 m³ bezahlt, 11 m³ geliefert · Dreingabe: 10 m³ geliefert, 9 m³ verrechnet"},en:{term:"Draufgabe vs. Dreingabe",erklaerung:"Both are discounts in kind. Draufgabe: more delivered than paid for. Dreingabe: less invoiced than delivered.",beispiel:"Draufgabe: 10 m³ paid, 11 m³ delivered · Dreingabe: 10 m³ delivered, 9 m³ invoiced"},hu:{term:"Ráadás (Draufgabe) és Dreingabe",erklaerung:"Mindkettő természetbeni engedmény. Ráadás: többet szállítanak, mint amennyit kifizettek. Dreingabe: kevesebbet számláznak, mint amennyit szállítanak.",beispiel:"Ráadás: 10 m³ kifizetve, 11 m³ szállítva · Dreingabe: 10 m³ szállítva, 9 m³ számlázva"}},{de:{term:"Einpunkt- vs. Zweipunktklausel",erklaerung:"Einpunktklausel: Risiko und Kosten gehen am selben Ort über („ab Werk“, „frei Haus“). Zweipunktklausel: an zwei Orten – Risiko schon beim ersten Frachtführer, Kosten erst später.",beispiel:"„Frachtfrei Bahnhof Graz“ = Zweipunktklausel"},en:{term:"One-point vs. two-point clause",erklaerung:"One-point clause: risk and costs pass at the same place (“ex works”, “free domicile”). Two-point clause: at two places – risk already at the first carrier, costs later.",beispiel:"“Carriage paid to Graz station” = two-point clause"},hu:{term:"Egypontos és kétpontos záradék",erklaerung:"Egypontos záradék: a kockázat és a költség ugyanott száll át („gyárból”, „házhoz szállítva”). Kétpontos: két helyen – a kockázat már az első fuvarozónál, a költség csak később.",beispiel:"„Fuvarköltség fizetve grazi állomásig” = kétpontos záradék"}},{de:{term:"Rabatt vs. Skonto",erklaerung:"Rabatt = Preisnachlass aus einem bestimmten Grund (Menge, Treue, Ereignis). Skonto = Abzug für Zahlung innerhalb der Kassafrist. Bezugskalkulation: zuerst Rabatt, dann Skonto.",beispiel:"10 % Mengenrabatt, dann 2 % Skonto vom verbilligten Preis"},en:{term:"Discount vs. cash discount",erklaerung:"Discount (Rabatt) = price reduction for a specific reason (quantity, loyalty, event). Cash discount (Skonto) = deduction for paying within the discount period. Calculation: discount first, then cash discount.",beispiel:"10% quantity discount, then 2% cash discount on the reduced price"},hu:{term:"Engedmény és skontó",erklaerung:"Engedmény (rabatt) = árengedmény meghatározott okból (mennyiség, hűség, esemény). Skontó = levonás a skontóhatáridőn belüli fizetésért. Kalkulációban: előbb engedmény, aztán skontó.",beispiel:"10% mennyiségi engedmény, majd 2% skontó a csökkentett árból"}}],"schriftverkehr-kaufvertrag":[{de:{term:"Anpreisung",erklaerung:"Unverbindliche Werbung des Verkäufers an viele (Katalog, Prospekt, Werbemail). Eine Bestellung darauf ist erst ein Angebot des Käufers – der Vertrag entsteht mit der Auftragsbestätigung.",beispiel:"Frühlingskatalog eines Verpackungsgroßhändlers"},en:{term:"Advertisement (invitation to treat)",erklaerung:"Non-binding advertising by the seller to many people (catalogue, brochure, promo email). An order based on it is only the buyer's offer – the contract arises with the order confirmation.",beispiel:"A packaging wholesaler's spring catalogue"},hu:{term:"Reklám (ajánlattételi felhívás)",erklaerung:"Az eladó nem kötelező érvényű reklámja sokak felé (katalógus, prospektus, reklám e-mail). Az erre adott megrendelés csak a vevő ajánlata – a szerződés a visszaigazolással jön létre.",beispiel:"Egy csomagolóanyag-nagykereskedő tavaszi katalógusa"}},{de:{term:"Anfrage",erklaerung:"Käufer bittet um Informationen oder ein Angebot – unverbindlich und formfrei. Allgemein (Katalog, Preisliste) oder speziell (Qualität, Preis, Bedingungen).",beispiel:"Loopy bittet drei Kakaohändler um ein Angebot für 200 kg"},en:{term:"Enquiry",erklaerung:"The buyer asks for information or an offer – non-binding and with no required form. General (catalogue, price list) or specific (quality, price, terms).",beispiel:"Loopy asks three cocoa dealers for an offer for 200 kg"},hu:{term:"Ajánlatkérés",erklaerung:"A vevő információt vagy ajánlatot kér – kötelezettség nélkül és formához kötöttség nélkül. Lehet általános (katalógus, árlista) vagy konkrét (minőség, ár, feltételek).",beispiel:"Loopy három kakaókereskedőtől kér ajánlatot 200 kg-ra"}},{de:{term:"Lieferschein vs. Gegenschein",erklaerung:"Lieferschein: listet die gelieferte Ware ohne Preise auf, bleibt beim Käufer. Gegenschein: Kopie, die der Käufer unterschreibt – geht als Übernahmebeweis an den Verkäufer zurück.",beispiel:"Mängel sofort auf beiden vermerken!"},en:{term:"Delivery note vs. counterfoil",erklaerung:"Delivery note: lists the goods delivered without prices, stays with the buyer. Counterfoil: copy signed by the buyer – returns to the seller as proof of receipt.",beispiel:"Note any defects on both immediately!"},hu:{term:"Szállítólevél és ellenlevél",erklaerung:"Szállítólevél: ár nélkül sorolja fel a szállított árut, a vevőnél marad. Ellenlevél: a vevő által aláírt másolat – az átvétel bizonyítékaként visszamegy az eladóhoz.",beispiel:"A hibákat azonnal jegyezd fel mindkettőre!"}},{de:{term:"Billigster vs. bester Anbieter",erklaerung:"Wer nur Preise vergleicht, findet den billigsten Anbieter. Werden auch Qualität, Lieferzeit, Bedingungen, Service und Termintreue verglichen, findet man den besten.",beispiel:"2 Cent teurer, aber pünktlich vor Ostern geliefert"},en:{term:"Cheapest vs. best supplier",erklaerung:"Comparing only prices finds the cheapest supplier. Also comparing quality, delivery time, terms, service and reliability finds the best one.",beispiel:"2 cents more expensive, but delivered on time before Easter"},hu:{term:"Legolcsóbb és legjobb ajánlattevő",erklaerung:"Aki csak az árakat hasonlítja össze, a legolcsóbb ajánlattevőt találja meg. Ha a minőséget, a szállítási időt, a feltételeket, a szervizt és a pontosságot is, akkor a legjobbat.",beispiel:"2 centtel drágább, de pontosan, húsvét előtt szállít"}},{de:{term:"Bezugsquellendatei",erklaerung:"Interne Sammlung von Infos über bisherige Lieferanten (Produkte, Preise, Termintreue). Erste Anlaufstelle bei der Lieferantensuche, vor externen Quellen wie Messen oder wlw.at.",beispiel:"Tabelle mit allen Kakaolieferanten der letzten Jahre"},en:{term:"Supplier file",erklaerung:"Internal collection of information on previous suppliers (products, prices, reliability). First port of call when looking for suppliers, before external sources like trade fairs or wlw.at.",beispiel:"Spreadsheet of all cocoa suppliers of recent years"},hu:{term:"Beszerzési forrás-nyilvántartás",erklaerung:"Belső adatgyűjtemény a korábbi beszállítókról (termékek, árak, pontosság). A beszállítókeresés első lépése, még a külső források (vásárok, wlw.at) előtt.",beispiel:"Táblázat az elmúlt évek összes kakaóbeszállítójáról"}}],"zahlungsformen-1jg":[{de:{term:"Halbbare Zahlung",erklaerung:"Nur einer der beiden Partner hat ein Konto: Einer zahlt bar ein oder bekommt Bargeld ausbezahlt. Bargeldlos = beide haben ein Konto.",beispiel:"Nachnahme, bar eingezahlte Zahlungsanweisung, Baranweisung"},en:{term:"Semi-cash payment",erklaerung:"Only one of the two parties has an account: one pays in cash or receives cash. Cashless = both have an account.",beispiel:"Cash on delivery, payment order paid in cash, cash money order"},hu:{term:"Félkészpénzes fizetés",erklaerung:"A két fél közül csak az egyiknek van számlája: az egyik készpénzt fizet be vagy készpénzt kap. Készpénz nélküli = mindkettőnek van számlája.",beispiel:"Utánvét, készpénzzel befizetett átutalási megbízás, készpénzes kifizetési utalvány"}},{de:{term:"Verfügungs- vs. Zeichnungsberechtigung",erklaerung:"Verfügungsberechtigt = Kontoinhaber:in, darf alles, auch das Konto löschen. Zeichnungsberechtigt = darf abheben, einzahlen und Daueraufträge einrichten, aber nicht löschen.",beispiel:"Loopy ist Inhaberin, ihre Buchhalterin zeichnungsberechtigt"},en:{term:"Power of disposal vs. signing authority",erklaerung:"Power of disposal = account holder, may do everything, including closing the account. Signing authority = may withdraw, deposit and set up standing orders, but not close it.",beispiel:"Loopy is the holder, her bookkeeper has signing authority"},hu:{term:"Rendelkezési jog és aláírási jog",erklaerung:"Rendelkezési jogosult = a számlatulajdonos, mindent megtehet, a számlát is megszüntetheti. Aláírási jogosult = pénzt vehet fel, befizethet, rendszeres átutalást állíthat be, de nem szüntetheti meg.",beispiel:"Loopy a tulajdonos, a könyvelője aláírási jogosult"}},{de:{term:"Oder-Konto vs. Und-Konto",erklaerung:"Gemeinschaftskonten mehrerer Inhaber:innen. Oder-Konto: Jede:r darf allein verfügen. Und-Konto: Nur alle gemeinsam dürfen verfügen.",beispiel:"Ehepaar mit Oder-Konto; zwei Gesellschafter:innen mit Und-Konto"},en:{term:"“Or” account vs. “and” account",erklaerung:"Joint accounts of several holders. “Or” account: each may act alone. “And” account: only all together may act.",beispiel:"Married couple with an “or” account; two partners with an “and” account"},hu:{term:"„Vagy”-számla és „és”-számla",erklaerung:"Több tulajdonos közös számlái. „Vagy”-számla: mindegyik egyedül is rendelkezhet. „És”-számla: csak együttesen rendelkezhetnek.",beispiel:"Házaspár „vagy”-számlával; két tulajdonostárs „és”-számlával"}},{de:{term:"SEPA-Dauerauftrag vs. SEPA-Lastschrift",erklaerung:"Dauerauftrag: gleiche Beträge regelmäßig, der Zahler beauftragt seine Bank. Lastschrift: wechselnde Beträge, der Empfänger bucht mit Einzugsermächtigung (Mandat) ab.",beispiel:"Miete per Dauerauftrag · Strom per Lastschrift"},en:{term:"SEPA standing order vs. SEPA direct debit",erklaerung:"Standing order: same amounts regularly, the payer instructs his bank. Direct debit: varying amounts, the payee collects with a mandate.",beispiel:"Rent by standing order · electricity by direct debit"},hu:{term:"SEPA rendszeres átutalás és SEPA beszedés",erklaerung:"Rendszeres átutalás: azonos összegek rendszeresen, a fizető bízza meg a bankját. Beszedés: változó összegek, a kedvezményezett szedi be felhatalmazással (mandátummal).",beispiel:"Lakbér rendszeres átutalással · áram beszedéssel"}},{de:{term:"Phishing",erklaerung:"Betrug mit gefälschten E-Mails, SMS oder Websites, die Zugangsdaten stehlen wollen. Banken fragen NIE per E-Mail nach Daten – Adresse selbst eintippen, auf https und Schloss achten.",beispiel:"„Ihr Konto wird gesperrt – bestätigen Sie hier Ihre PIN“"},en:{term:"Phishing",erklaerung:"Fraud using fake emails, texts or websites to steal login data. Banks NEVER ask for data by email – type the address yourself, look for https and the padlock.",beispiel:"“Your account will be blocked – confirm your PIN here”"},hu:{term:"Adathalászat (phishing)",erklaerung:"Csalás hamis e-mailekkel, SMS-ekkel vagy weboldalakkal, amelyek belépési adatokat akarnak ellopni. A bank SOHA nem kér adatot e-mailben – a címet magad írd be, figyelj a https-re és a lakatra.",beispiel:"„Számláját letiltjuk – erősítse meg itt a PIN-kódját”"}}],"unzuverlaessige-verkaeufer":[{de:{term:"Fixgeschäft vs. gewöhnliches Termingeschäft",erklaerung:"Fixgeschäft (genauer Termin/Zweck): Rechtsfolgen sofort bei Überschreiten. Termingeschäft (ungefährer Termin): erst nach Mahnung mit angemessener Nachfrist (meist 14 Tage).",beispiel:"Hochzeitstorte „fix am 20. April“ · Verpackungen „binnen 2 Wochen“"},en:{term:"Fixed-date vs. ordinary forward transaction",erklaerung:"Fixed-date (exact date/purpose): legal consequences as soon as it is missed. Forward transaction (approximate date): only after a reminder with a reasonable grace period (usually 14 days).",beispiel:"Wedding cake “fixed on 20 April” · packaging “within 2 weeks”"},hu:{term:"Fix határidős és szokásos határidős ügylet",erklaerung:"Fix határidős (pontos időpont/cél): a jogkövetkezmények a határidő túllépésekor azonnal beállnak. Szokásos határidős (hozzávetőleges időpont): csak póthatáridős (általában 14 nap) felszólítás után.",beispiel:"Esküvői torta „fixen április 20-án” · csomagolás „2 héten belül”"}},{de:{term:"Gewährleistung vs. Garantie",erklaerung:"Gewährleistung: gesetzlich, der Verkäufer haftet für Mängel, die schon bei Übergabe da waren. Garantie: freiwillig (Hersteller oder Verkäufer), für Mängel innerhalb eines vereinbarten Zeitraums.",beispiel:"2 Jahre Gewährleistung + 5 Jahre Herstellergarantie auf einen Kühlschrank"},en:{term:"Statutory warranty vs. guarantee",erklaerung:"Statutory warranty: required by law, the seller is liable for defects present at handover. Guarantee: voluntary (manufacturer or seller), for defects within an agreed period.",beispiel:"2-year statutory warranty + 5-year manufacturer's guarantee on a fridge"},hu:{term:"Szavatosság és garancia",erklaerung:"Szavatosság: törvényi, az eladó felel az átadáskor már meglévő hibákért. Garancia (jótállás): önkéntes (gyártó vagy eladó), a megállapodott időszakon belül jelentkező hibákra.",beispiel:"2 év szavatosság + 5 év gyártói garancia egy hűtőszekrényre"}},{de:{term:"Produkthaftung (PHG)",erklaerung:"Gesetzliche Haftung von Hersteller/Importeur für Personen- und Sachschäden durch ein fehlerhaftes Produkt – auch ohne Verschulden. Bei Sachschäden 500 € Selbstbehalt, bis 10 Jahre.",beispiel:"Akku eines Handys explodiert und beschädigt das Sofa"},en:{term:"Product liability (PHG)",erklaerung:"Statutory liability of the manufacturer/importer for personal injury and property damage caused by a defective product – even without fault. €500 deductible for property damage, up to 10 years.",beispiel:"A phone battery explodes and damages the sofa"},hu:{term:"Termékfelelősség (PHG)",erklaerung:"A gyártó/importőr törvényi felelőssége a hibás termék okozta személyi és dologi károkért – vétkességtől függetlenül. Dologi kárnál 500 € önrész, legfeljebb 10 évig.",beispiel:"Felrobban egy mobiltelefon akkumulátora, és megrongálja a kanapét"}},{de:{term:"Gewährleistungsfristen",erklaerung:"Neue bewegliche Sachen 2 Jahre ab Übergabe · gebrauchte 2 Jahre (1 Jahr vereinbar) · unbewegliche Sachen 3 Jahre · arglistig verschwiegene Mängel 30 Jahre. Danach 3 Monate für eine Klage.",beispiel:"Laptop 2 Jahre · Wohnung 3 Jahre"},en:{term:"Statutory warranty periods",erklaerung:"New movable goods 2 years from handover · used 2 years (1 year can be agreed) · immovable property 3 years · fraudulently concealed defects 30 years. Then 3 months to sue.",beispiel:"Laptop 2 years · flat 3 years"},hu:{term:"Szavatossági határidők",erklaerung:"Új ingó dolgok 2 év az átadástól · használtak 2 év (1 év megállapodható) · ingatlanok 3 év · csalárdul elhallgatott hibák 30 év. Utána 3 hónap van a perindításra.",beispiel:"Laptop 2 év · lakás 3 év"}},{de:{term:"Fehlerhafte Rechnung",erklaerung:"Abweichende Preise/Bedingungen, Rechenfehler oder fehlende UStG-Angaben. Nur der Aussteller darf korrigieren (neue Rechnung); fehlt ein UStG-Bestandteil, gibt es keinen Vorsteuerabzug.",beispiel:"Vereinbarter Rabatt fehlt, UID-Nummer fehlt"},en:{term:"Incorrect invoice",erklaerung:"Different prices/terms, calculation errors or missing details required by the VAT Act. Only the issuer may correct it (new invoice); if a VAT element is missing, no input VAT deduction.",beispiel:"Agreed discount missing, VAT ID missing"},hu:{term:"Hibás számla",erklaerung:"Eltérő árak/feltételek, számítási hiba vagy hiányzó áfatörvényi adatok. Csak a kiállító javíthatja (új számla); ha hiányzik egy áfatörvényi elem, nincs előzetesadó-levonás.",beispiel:"Hiányzik a megállapodott engedmény vagy a közösségi adószám"}}]},n={"unzuverlaessige-kaeufer":[{de:{term:"Hinterlegung (bei Annahmeverzug)",erklaerung:"Der Verkäufer gibt die nicht angenommene Ware bei Gericht in Verwahrung und fordert den Käufer zur Zahlung auf. Gilt bei C2C, B2C und B2B.",beispiel:"Ein Kunde holt bestellte Pralinen nicht ab – Loopy hinterlegt sie bei Gericht."},en:{term:"Deposit with the court (default of acceptance)",erklaerung:"The seller hands the goods that were not accepted over to the court for safekeeping and asks the buyer to pay. Applies in C2C, B2C and B2B.",beispiel:"A customer does not collect ordered chocolates – Loopy deposits them with the court."},hu:{term:"Bírósági letét (átvételi késedelemnél)",erklaerung:"Az eladó az át nem vett árut bírósági letétbe helyezi, és felszólítja a vevőt a fizetésre. C2C, B2C és B2B ügyleteknél is alkalmazható.",beispiel:"Egy vevő nem viszi el a megrendelt bonbonokat – Loopy bírósági letétbe helyezi őket."}},{de:{term:"Selbsthilfeverkauf",erklaerung:"Nur bei B2B: Der Verkäufer lässt die nicht angenommene Ware nach Androhung versteigern. Der Erlös wird auf den Kaufpreis angerechnet.",beispiel:"Ein Hotel nimmt 200 kg Fruchtgummi nicht an – Loopy lässt sie nach Androhung versteigern."},en:{term:"Self-help sale",erklaerung:"B2B only: after giving notice, the seller has the goods that were not accepted auctioned. The proceeds are credited against the purchase price.",beispiel:"A hotel refuses 200 kg of fruit gums – after notice, Loopy has them auctioned."},hu:{term:"Önsegélyes eladás",erklaerung:"Csak B2B-ügyleteknél: az eladó előzetes figyelmeztetés után elárverezteti az át nem vett árut. A befolyt összeget beszámítják a vételárba.",beispiel:"Egy szálloda nem veszi át a 200 kg gumicukrot – Loopy figyelmeztetés után elárverezteti."}},{de:{term:"Mahnspesen",erklaerung:"Kosten des Mahnens, die der Verkäufer verlangen kann: B2B (UGB) 40 € Pauschale, B2C/C2C (ABGB) in angemessener Höhe – sofern vertraglich nichts anderes vereinbart ist."},en:{term:"Reminder fees",erklaerung:"Costs of sending reminders that the seller can charge: B2B (UGB) a €40 flat fee, B2C/C2C (ABGB) a reasonable amount – unless the contract says otherwise."},hu:{term:"Felszólítási (behajtási) költség",erklaerung:"A felszólítás költségei, amelyeket az eladó követelhet: B2B (UGB) 40 € átalány, B2C/C2C (ABGB) méltányos összeg – ha a szerződés másként nem rendelkezik."}},{de:{term:"Bedingter Zahlungsbefehl",erklaerung:"Wird im gerichtlichen Mahnverfahren (bis 75.000 €) erlassen: Der Schuldner muss binnen 14 Tagen zahlen oder binnen 4 Wochen Einspruch erheben – sonst wird er rechtskräftig."},en:{term:"Conditional payment order",erklaerung:"Issued in the court dunning procedure (up to €75,000): the debtor must pay within 14 days or object within 4 weeks – otherwise it becomes final."},hu:{term:"Feltételes fizetési meghagyás",erklaerung:"A bírósági fizetési meghagyásos eljárásban (75 000 €-ig) bocsátják ki: az adósnak 14 napon belül fizetnie kell, vagy 4 héten belül ellentmondhat – különben jogerős lesz."}},{de:{term:"Annahmeverzug vs. Zahlungsverzug",erklaerung:"Annahmeverzug: Der Käufer nimmt die vertragsgemäße Ware nicht an. Zahlungsverzug: Der Käufer zahlt nicht rechtzeitig – die häufigste Pflichtverletzung des Käufers."},en:{term:"Default of acceptance vs. default in payment",erklaerung:"Default of acceptance: the buyer does not accept goods that match the contract. Default in payment: the buyer does not pay on time – the buyer's most common breach of duty."},hu:{term:"Átvételi késedelem vs. fizetési késedelem",erklaerung:"Átvételi késedelem: a vevő nem veszi át a szerződésszerű árut. Fizetési késedelem: a vevő nem fizet időben – ez a vevő leggyakoribb kötelezettségszegése."}}],rechtsdurchsetzung:[{de:{term:"Mediation",erklaerung:"Ein neutraler Vermittler (Mediator:in) hilft den Streitparteien, selbst eine Lösung zu finden. Er entscheidet nicht – das Ergebnis ist nicht bindend.",beispiel:"Loopy und ihr Vermieter streiten über Reparaturkosten und gehen zu einer Mediatorin."},en:{term:"Mediation",erklaerung:"A neutral facilitator (mediator) helps the parties find a solution themselves. The mediator does not decide – the outcome is not binding.",beispiel:"Loopy and her landlord disagree about repair costs and see a mediator."},hu:{term:"Mediáció",erklaerung:"Egy semleges közvetítő (mediátor) segít a vitázó feleknek, hogy maguk találjanak megoldást. Nem dönt – az eredmény nem kötelező.",beispiel:"Loopy és a bérbeadója a javítási költségeken vitatkozik, és mediátorhoz fordulnak."}},{de:{term:"Schlichtungsstelle",erklaerung:"Außergerichtliche Stelle, die bei einem Streit eine Empfehlung zur Lösung gibt. Die Empfehlung ist rechtlich nicht bindend."},en:{term:"Conciliation board",erklaerung:"Out-of-court body that gives a recommendation for resolving a dispute. The recommendation is not legally binding."},hu:{term:"Békéltető testület",erklaerung:"Bíróságon kívüli szerv, amely vitás ügyben ajánlást tesz a megoldásra. Az ajánlás jogilag nem kötelező."}},{de:{term:"Schiedsgericht",erklaerung:"Privates Gericht, das die Vertragspartner vorher vertraglich vereinbaren. Als einzige Alternative zum staatlichen Gericht entscheidet es rechtlich bindend."},en:{term:"Arbitral tribunal",erklaerung:"A private court that the contracting parties agree on in advance in their contract. It is the only alternative to state courts whose decision is legally binding."},hu:{term:"Választottbíróság",erklaerung:"Magánbíróság, amelyben a felek előre, szerződésben állapodnak meg. Az állami bíróság alternatívái közül egyedül az ő döntése jogilag kötelező."}},{de:{term:"Kulanzweg",erklaerung:"Beide Seiten gehen freiwillig aufeinander zu und einigen sich ohne Dritte – oft um eine wichtige Geschäftsbeziehung zu erhalten.",beispiel:"Loopy gewährt einem Stammkunden für eine verspätete Lieferung 10 % Nachlass."},en:{term:"Goodwill approach",erklaerung:"Both sides voluntarily meet each other halfway and agree without a third party – often to keep an important business relationship.",beispiel:"Loopy gives a regular customer 10% off for a late delivery."},hu:{term:"Méltányossági (kulancia) út",erklaerung:"A felek önként engednek egymásnak, és harmadik fél nélkül megegyeznek – gyakran azért, hogy megőrizzenek egy fontos üzleti kapcsolatot.",beispiel:"Loopy egy törzsvásárlónak 10 % kedvezményt ad egy késve érkezett szállítás miatt."}},{de:{term:"Nachteile eines Rechtsstreits",erklaerung:"Langwierig (dauert oft lange), ungewiss (Ausgang offen), teuer (Verlierer zahlt alle Kosten) und rufschädigend (meist Ende der Geschäftsbeziehung)."},en:{term:"Disadvantages of a lawsuit",erklaerung:"Lengthy (often takes a long time), uncertain (outcome open), expensive (the loser pays all costs) and damaging to reputation (usually ends the business relationship)."},hu:{term:"A pereskedés hátrányai",erklaerung:"Hosszadalmas (sokáig tart), bizonytalan (nyitott a kimenetele), drága (a vesztes fizet minden költséget) és rontja a hírnevet (általában véget vet az üzleti kapcsolatnak)."}},{de:{term:"Rechte durchsetzen – 5 Schritte",erklaerung:"1. Interesse klären (Was will ich?) 2. Partner benachrichtigen (bis wann?) 3. Abwägen 4. Beratung einholen 5. Entscheiden: außergerichtliche Einigung oder Prozess."},en:{term:"Enforcing your rights – 5 steps",erklaerung:"1. Clarify your interest (What do I want?) 2. Notify the partner (by when?) 3. Weigh up 4. Get advice 5. Decide: out-of-court settlement or lawsuit."},hu:{term:"Jogérvényesítés – 5 lépés",erklaerung:"1. Érdek tisztázása (Mit akarok?) 2. A partner értesítése (meddig?) 3. Mérlegelés 4. Tanácsadás 5. Döntés: peren kívüli megegyezés vagy per."}},{de:{term:"Außergerichtliche Einigung",erklaerung:"Lösung eines Streits ohne Gerichtsurteil, z. B. über Kulanz, Mediation oder eine Schlichtungsstelle. Spart Zeit und Kosten und schont die Geschäftsbeziehung."},en:{term:"Out-of-court settlement",erklaerung:"Resolving a dispute without a court judgment, e.g. through goodwill, mediation or a conciliation board. Saves time and money and protects the business relationship."},hu:{term:"Peren kívüli megegyezés",erklaerung:"Vita rendezése bírósági ítélet nélkül, pl. méltányossági úton, mediációval vagy békéltető testülettel. Időt és költséget takarít meg, és kíméli az üzleti kapcsolatot."}}],"unternehmensgruendung-schritte":[{de:{term:"Befähigungsnachweis",erklaerung:"Beweis für die nötigen Fachkenntnisse, z. B. Meisterprüfung oder HAK-Abschluss plus Praxis. Pflicht für reglementierte Gewerbe.",beispiel:"Eine Friseurin braucht die Meisterprüfung, um einen eigenen Salon zu eröffnen."},en:{term:"Proof of qualification",erklaerung:"Evidence of the required expertise, e.g. a master craftsman's exam or a HAK diploma plus practical experience. Mandatory for regulated trades.",beispiel:"A hairdresser needs the master exam to open her own salon."},hu:{term:"Képesítési igazolás",erklaerung:"A szükséges szakértelem bizonyítéka, pl. mestervizsga vagy HAK-érettségi plusz gyakorlat. A szabályozott iparágaknál kötelező.",beispiel:"Egy fodrásznőnek mestervizsga kell ahhoz, hogy saját szalont nyisson."}},{de:{term:"Freies vs. reglementiertes Gewerbe",erklaerung:"Freies Gewerbe: nur allgemeine Voraussetzungen (z. B. Werbeagentur). Reglementiertes Gewerbe: zusätzlich Befähigungsnachweis (z. B. Bäcker), teils auch Zuverlässigkeitsprüfung (Baumeister)."},en:{term:"Free vs. regulated trade",erklaerung:"Free trade: only the general requirements (e.g. advertising agency). Regulated trade: also proof of qualification (e.g. baker), sometimes a reliability check too (master builder)."},hu:{term:"Szabad vs. szabályozott ipar",erklaerung:"Szabad ipar: csak az általános feltételek (pl. reklámügynökség). Szabályozott ipar: képesítési igazolás is kell (pl. pék), egyes esetekben megbízhatósági vizsgálat is (építőmester)."}},{de:{term:"USP (Unique Selling Proposition)",erklaerung:"Alleinstellungsmerkmal – der Vorteil, durch den ein Angebot besser ist als das der Konkurrenz und Kund:innen überzeugt.",beispiel:"Loopy bietet als einziges Geschäft der Stadt zuckerfreie Pralinen nach Wunsch an."},en:{term:"USP (unique selling proposition)",erklaerung:"The distinctive advantage that makes an offer better than the competition's and convinces customers.",beispiel:"Loopy is the only shop in town offering made-to-order sugar-free chocolates."},hu:{term:"USP (egyedi értékajánlat)",erklaerung:"Az az egyedi előny, amely miatt egy ajánlat jobb a versenytársakénál, és meggyőzi a vevőket.",beispiel:"Loopy az egyetlen bolt a városban, amely egyedi rendelésre cukormentes bonbont készít."}},{de:{term:"Unternehmensübernahme",erklaerung:"Man kauft ein bestehendes Unternehmen. Vorteile: weniger Investitionen, eingespielte Abläufe, Kund:innen und Lieferanten vorhanden. Nachteil: Mängel werden mit übernommen."},en:{term:"Business takeover",erklaerung:"You buy an existing business. Advantages: lower investment, established processes, existing customers and suppliers. Disadvantage: its defects are taken over too."},hu:{term:"Vállalkozás átvétele",erklaerung:"Egy meglévő vállalkozás megvásárlása. Előnyök: kisebb beruházás, bejáratott folyamatok, meglévő vevők és szállítók. Hátrány: a hiányosságokat is átvesszük."}},{de:{term:"Firmenkern & Firmenzusatz",erklaerung:"Die Firma besteht aus dem frei wählbaren Firmenkern und dem Firmenzusatz, der die Rechtsform zeigt.",beispiel:"„Lisa Berger“ (Kern) + „e. U.“ (Zusatz) = Lisa Berger e. U."},en:{term:"Core name & legal form suffix",erklaerung:"A company name (Firma) consists of the freely chosen core name and the suffix that shows the legal form.",beispiel:"‘Lisa Berger’ (core) + ‘e. U.’ (suffix) = Lisa Berger e. U."},hu:{term:"Vezérszó és cégforma-toldat",erklaerung:"A cégnév a szabadon választható vezérszóból és a jogi formát jelző toldatból áll.",beispiel:"„Lisa Berger” (vezérszó) + „e. U.” (toldat) = Lisa Berger e. U."}}],"wahl-der-rechtsform-1jg":[{de:{term:"Kriterien der Rechtsformwahl",erklaerung:"Anzahl der Eigentümer, Kapitalaufbringung, Haftung, Leitungsbefugnis/Kontrolle, Erfolgsverteilung und Art der Buchführung."},en:{term:"Criteria for choosing a legal form",erklaerung:"Number of owners, raising capital, liability, management authority/control, profit distribution and type of bookkeeping."},hu:{term:"A jogi forma választásának szempontjai",erklaerung:"A tulajdonosok száma, a tőke előteremtése, a felelősség, a vezetési jogkör/ellenőrzés, az eredmény felosztása és a könyvvezetés módja."}},{de:{term:"Vollhafter",erklaerung:"Haftet persönlich und unbeschränkt für die Schulden des Unternehmens – auch mit dem Privatvermögen.",beispiel:"Einzelunternehmerin Sophie haftet für Geschäftsschulden auch mit ihrem Sparbuch."},en:{term:"Fully liable owner",erklaerung:"Is personally and unlimitedly liable for the business's debts – including with private assets.",beispiel:"Sole trader Sophie is liable for business debts with her savings account too."},hu:{term:"Korlátlanul felelős tulajdonos",erklaerung:"Személyesen és korlátlanul felel a vállalkozás tartozásaiért – a magánvagyonával is.",beispiel:"Sophie egyéni vállalkozó az üzleti tartozásokért a takarékbetétjével is felel."}},{de:{term:"Eingetragener Unternehmer (e. U.)",erklaerung:"Einzelunternehmer, der im Firmenbuch eingetragen ist. Pflicht ab den Umsatzgrenzen für die doppelte Buchhaltung, freiwillig schon früher möglich.",beispiel:"Lisa Berger e. U."},en:{term:"Registered trader (e. U.)",erklaerung:"A sole trader entered in the commercial register. Mandatory once the turnover thresholds for double-entry bookkeeping are reached, possible voluntarily earlier.",beispiel:"Lisa Berger e. U."},hu:{term:"Bejegyzett vállalkozó (e. U.)",erklaerung:"Cégjegyzékbe bejegyzett egyéni vállalkozó. A kettős könyvvitel forgalmi értékhatáraitól kötelező, önként korábban is lehetséges.",beispiel:"Lisa Berger e. U."}},{de:{term:"Umsatzgrenzen doppelte Buchhaltung",erklaerung:"Ein Einzelunternehmer muss doppelt buchen, wenn der Umsatz 1 Mio. € in einem Jahr oder zwei Jahre hintereinander je 700.000 € übersteigt. Darunter reicht die E/A-Rechnung."},en:{term:"Turnover thresholds for double-entry bookkeeping",erklaerung:"A sole trader must keep double-entry books if turnover exceeds €1 million in one year or €700,000 in each of two consecutive years. Below that, cash-basis accounts are enough."},hu:{term:"A kettős könyvvitel árbevételi határai",erklaerung:"Az egyéni vállalkozó kettős könyvvitelre köteles, ha árbevétele egy évben meghaladja az 1 millió €-t, vagy két egymást követő évben a 700 000 €-t. Ez alatt elég a bevétel-kiadás nyilvántartás."}},{de:{term:"E/A-Rechnung",erklaerung:"Einnahmen-Ausgaben-Rechnung: einfache Gewinnermittlung, bei der nur Einnahmen und Ausgaben gegenübergestellt werden. Typisch für kleine Einzelunternehmen."},en:{term:"Cash-basis accounting (income-expenditure accounts)",erklaerung:"A simple way of determining profit by comparing only income and expenditure. Typical of small sole proprietorships."},hu:{term:"Bevétel-kiadás nyilvántartás",erklaerung:"Egyszerű nyereségmeghatározás, amelynél csak a bevételeket és a kiadásokat állítják szembe egymással. Kis egyéni vállalkozásokra jellemző."}},{de:{term:"Personengesellschaft",erklaerung:"Gesellschaft, bei der die Personen der Gesellschafter im Vordergrund stehen und mindestens ein Gesellschafter persönlich haftet. Beispiele: OG, KG."},en:{term:"Partnership",erklaerung:"A company in which the individual partners are central and at least one partner is personally liable. Examples: OG, KG."},hu:{term:"Személyegyesítő társaság",erklaerung:"Olyan társaság, amelyben a tagok személye áll előtérben, és legalább egy tag személyesen felel. Példák: OG, KG."}},{de:{term:"Kapitalgesellschaft",erklaerung:"Gesellschaft, bei der das eingebrachte Kapital im Vordergrund steht. Für Schulden haftet grundsätzlich nur das Gesellschaftsvermögen. Beispiele: GmbH, AG."},en:{term:"Corporation (capital company)",erklaerung:"A company in which the capital contributed is central. In principle only the company's assets are liable for debts. Examples: GmbH, AG."},hu:{term:"Tőkeegyesítő társaság",erklaerung:"Olyan társaság, amelyben a befektetett tőke áll előtérben. A tartozásokért főszabály szerint csak a társaság vagyona felel. Példák: GmbH, AG."}}],"businessplan-1jg":[{de:{term:"Executive Summary",erklaerung:"Kurze Zusammenfassung ganz am Anfang des Businessplans mit den wichtigsten Aussagen und Kennzahlen – oft das Einzige, was Kapitalgeber zuerst lesen."},en:{term:"Executive summary",erklaerung:"Short summary at the very beginning of the business plan with the key statements and figures – often the part investors read first."},hu:{term:"Vezetői összefoglaló",erklaerung:"Rövid összefoglaló az üzleti terv legelején a legfontosabb állításokkal és mutatókkal – a befektetők gyakran először csak ezt olvassák el."}},{de:{term:"4 Funktionen des Businessplans",erklaerung:"Beurteilen (ist die Idee realisierbar?), überzeugen (Kapitalgeber, Förderstellen), planen (Umsetzung) und steuern (Gründungsphase lenken, Ziele kontrollieren)."},en:{term:"4 functions of the business plan",erklaerung:"Assess (is the idea feasible?), convince (investors, funding bodies), plan (implementation) and steer (guide the start-up phase, monitor goals)."},hu:{term:"Az üzleti terv 4 funkciója",erklaerung:"Megítélés (megvalósítható-e az ötlet?), meggyőzés (befektetők, támogatók), tervezés (megvalósítás) és irányítás (az alapítási szakasz vezetése, a célok ellenőrzése)."}},{de:{term:"Finanzplanung",erklaerung:"Teil des Businessplans mit Kapitalbedarf, Finanzierung (Eigen- und Fremdkapital) und geplantem Umsatz. Zeigt, ob das Vorhaben finanzierbar ist."},en:{term:"Financial planning",erklaerung:"Part of the business plan covering capital requirement, financing (equity and borrowed capital) and planned turnover. Shows whether the project can be financed."},hu:{term:"Pénzügyi terv",erklaerung:"Az üzleti terv része, amely a tőkeszükségletet, a finanszírozást (saját és idegen tőke) és a tervezett árbevételt tartalmazza. Megmutatja, finanszírozható-e a vállalkozás."}},{de:{term:"Kapitalbedarf",erklaerung:"Der Geldbetrag, den man für die Gründung braucht – z. B. für Einrichtung, Maschinen, Wareneinkauf und Miete bis zu den ersten Einnahmen.",beispiel:"Loopy braucht 40.000 € für Kühlvitrine und Ladeneinrichtung."},en:{term:"Capital requirement",erklaerung:"The amount of money needed to start the business – e.g. for fittings, machines, purchasing goods and rent until the first income comes in.",beispiel:"Loopy needs €40,000 for a refrigerated display case and shop fittings."},hu:{term:"Tőkeszükséglet",erklaerung:"Az alapításhoz szükséges pénzösszeg – pl. berendezésre, gépekre, árubeszerzésre és bérleti díjra az első bevételekig.",beispiel:"Loopynak 40 000 € kell hűtővitrinre és bolti berendezésre."}},{de:{term:"Umsetzungsfahrplan",erklaerung:"Letzter Teil des Businessplans: Meilensteine mit konkretem Datum, die zeigen, wann welcher Schritt der Gründung erledigt wird.",beispiel:"15. Februar: Online-Shop live · 1. März: Eröffnung"},en:{term:"Implementation roadmap",erklaerung:"Last part of the business plan: milestones with concrete dates showing when each step of the start-up will be completed.",beispiel:"15 February: online shop live · 1 March: opening"},hu:{term:"Megvalósítási ütemterv",erklaerung:"Az üzleti terv utolsó része: konkrét dátumokkal ellátott mérföldkövek, amelyek megmutatják, mikor melyik alapítási lépés készül el.",beispiel:"Február 15.: él a webshop · Március 1.: megnyitás"}},{de:{term:"Chancen und Risiken",erklaerung:"Abschnitt im Businessplan, der ehrlich zeigt, was den Erfolg fördern und was ihn gefährden kann. Macht den Plan für Kapitalgeber glaubwürdig.",beispiel:"Chance: Trend zu Geschenkboxen · Risiko: steigende Kakaopreise"},en:{term:"Opportunities and risks",erklaerung:"Section of the business plan that honestly shows what can promote success and what can endanger it. Makes the plan credible for investors.",beispiel:"Opportunity: trend towards gift boxes · Risk: rising cocoa prices"},hu:{term:"Esélyek és kockázatok",erklaerung:"Az üzleti terv azon része, amely őszintén bemutatja, mi segítheti és mi veszélyeztetheti a sikert. Hitelessé teszi a tervet a befektetők szemében.",beispiel:"Esély: az ajándékdobozok divatja · Kockázat: emelkedő kakaóárak"}},{de:{term:"Marge berechnen",erklaerung:"Marge pro Stück = Verkaufspreis − Einkaufs- bzw. Herstellkosten. Gesamtmarge = Marge pro Stück · verkaufte Menge.",beispiel:"(14,90 € − 9,40 €) · 300 Boxen = 1.650 €"},en:{term:"Calculating the margin",erklaerung:"Margin per unit = selling price − purchase or production cost. Total margin = margin per unit · quantity sold.",beispiel:"(€14.90 − €9.40) · 300 boxes = €1,650"},hu:{term:"Az árrés kiszámítása",erklaerung:"Egységnyi árrés = eladási ár − beszerzési vagy előállítási költség. Teljes árrés = egységnyi árrés · eladott mennyiség.",beispiel:"(14,90 € − 9,40 €) · 300 doboz = 1 650 €"}}],"vertraege-mitarbeiter":[{de:{term:"„Echter“ Arbeitsvertrag",erklaerung:"Man schuldet persönliche Arbeitskraft, ist weisungsgebunden, hat fixe Arbeitszeit und fixen Arbeitsort. Arbeitsmittel und Risiko liegen beim Arbeitgeber.",beispiel:"Verkäuferin oder Lehrling in Loopys Candy Store"},en:{term:"‘Real’ employment contract",erklaerung:"You owe your personal labour, are bound by instructions and have fixed working hours and a fixed place of work. Equipment and risk lie with the employer.",beispiel:"Sales assistant or apprentice in Loopy's Candy Store"},hu:{term:"„Valódi” munkaszerződés",erklaerung:"Személyes munkavégzéssel tartozik, utasításhoz kötött, rögzített munkaidővel és munkahellyel. A munkaeszközök és a kockázat a munkáltatónál vannak.",beispiel:"Eladó vagy tanuló Loopy édességboltjában"}},{de:{term:"Freier Dienstvertrag",erklaerung:"Man schuldet Arbeitskraft, aber ohne persönliche Abhängigkeit: keine Weisungen, freie Zeit und freier Ort, Vertretung möglich. Arbeitsmittel meist vom Auftraggeber.",beispiel:"Dateneingabe von zu Hause aus"},en:{term:"Freelance service contract",erklaerung:"You owe labour, but without personal dependence: no instructions, free choice of time and place, substitution possible. Equipment usually from the client.",beispiel:"Data entry from home"},hu:{term:"„Szabad” szolgálati szerződés (freier Dienstvertrag)",erklaerung:"Munkaerővel tartozik, de személyes függőség nélkül: nincs utasítás, szabad idő- és helyválasztás, helyettesítés lehetséges. A munkaeszközök többnyire a megbízótól.",beispiel:"Otthonról végzett adatrögzítés"}},{de:{term:"Werkvertrag",erklaerung:"Man schuldet einen Erfolg bzw. ein Werk, arbeitet mit eigenen Mitteln und auf eigenes Risiko. Geld gibt es erst bei Fertigstellung; für Fehler haftet man (Gewährleistung).",beispiel:"Website gestalten für 7.000 €"},en:{term:"Contract for work",erklaerung:"You owe a result or a piece of work, using your own equipment and at your own risk. Payment only on completion; you are liable for defects (warranty).",beispiel:"Designing a website for €7,000"},hu:{term:"Vállalkozási szerződés",erklaerung:"Eredménnyel, illetve művel tartozik, saját eszközökkel és saját kockázatra dolgozik. Díj csak elkészüléskor jár; a hibákért szavatossággal felel.",beispiel:"Weboldal készítése 7 000 €-ért"}},{de:{term:"Formfreiheit des Arbeitsvertrags",erklaerung:"Ein Arbeitsvertrag kann auch mündlich gültig abgeschlossen werden. Gibt es keinen schriftlichen Vertrag, muss der Arbeitgeber aber sofort einen Dienstzettel ausstellen."},en:{term:"No form required for employment contracts",erklaerung:"An employment contract is valid even if concluded orally. If there is no written contract, however, the employer must immediately issue a Dienstzettel."},hu:{term:"A munkaszerződés alaki kötetlensége",erklaerung:"A munkaszerződés szóban is érvényesen megköthető. Ha nincs írásos szerződés, a munkáltatónak azonnal ki kell állítania a Dienstzettelt."}},{de:{term:"Kollektivvertrag (KV)",erklaerung:"Vertrag zwischen den Sozialpartnern (Arbeitgeber- und Arbeitnehmervertretung) für eine ganze Branche – regelt z. B. Mindestlöhne und Sonderzahlungen. Steht im Dienstzettel samt Einstufung."},en:{term:"Collective agreement",erklaerung:"Agreement between the social partners (employer and employee representatives) for a whole sector – governs e.g. minimum wages and bonus payments. Listed in the Dienstzettel with the pay grade."},hu:{term:"Kollektív szerződés",erklaerung:"A szociális partnerek (munkáltatói és munkavállalói érdekképviseletek) megállapodása egy egész ágazatra – szabályozza pl. a minimálbért és a különkifizetéseket. A besorolással együtt a Dienstzettelben szerepel."}},{de:{term:"Probezeit",erklaerung:"Zeit am Beginn des Arbeitsverhältnisses (in der Regel höchstens 1 Monat), in der beide Seiten das Arbeitsverhältnis jederzeit ohne Angabe von Gründen lösen können."},en:{term:"Probationary period",erklaerung:"Period at the start of employment (usually at most 1 month) during which either side can end the employment at any time without giving reasons."},hu:{term:"Próbaidő",erklaerung:"A munkaviszony elején lévő időszak (általában legfeljebb 1 hónap), amely alatt bármelyik fél bármikor, indoklás nélkül megszüntetheti a munkaviszonyt."}},{de:{term:"Mitarbeitervorsorgekasse",erklaerung:"Einrichtung, an die der Arbeitgeber laufend Beiträge für die „Abfertigung neu“ zahlt. Sie wird im Dienstzettel angegeben."},en:{term:"Employee severance fund",erklaerung:"Fund to which the employer makes ongoing contributions for the ‘new severance pay’ (Abfertigung neu). It is stated in the Dienstzettel."},hu:{term:"Munkavállalói előgondoskodási pénztár",erklaerung:"Pénztár, amelybe a munkáltató folyamatosan befizeti az „új végkielégítés” (Abfertigung neu) járulékait. A Dienstzettelben fel kell tüntetni."}}]},s=e(t,r,n);export{s as default};
